import React, { useEffect, useState } from "react";
import { useParams, useNavigate } from "react-router-dom";
import axios from "axios";
import "../styles/UserGig.css";

const UserGig = () => {
  const { gigId } = useParams();
  const [gig, setGig] = useState(null);
  const navigate = useNavigate();

  useEffect(() => {
    const fetchGig = async () => {
      try {
        const res = await axios.get(`http://localhost:5000/api/gigs/${gigId}`);
        setGig(res.data);
      } catch (err) {
        console.error("Error fetching gig:", err);
      }
    };
    fetchGig();
  }, [gigId]);

  if (!gig) return <div className="gig-posting-container">Loading...</div>;

  return (
    <div className="gig-posting-container">
      <h2 className="gig-posting-title">Gig Posting</h2>

      <div className="gig-info-group">
        <label className="gig-info-label">Title</label>
        <input className="gig-info-value" value={gig.title} readOnly />
      </div>

      <div className="gig-info-group">
        <label className="gig-info-label">Gig Type</label>
        <input className="gig-info-value" value={gig.gigType} readOnly />
      </div>

      <div className="gig-info-group">
        <label className="gig-info-label">Genre</label>
        <input
          className="gig-info-value"
          value={Array.isArray(gig.genre) ? gig.genre.join(", ") : gig.genre}
          readOnly
        />
      </div>

      <div className="gig-info-group">
        <label className="gig-info-label">City</label>
        <input className="gig-info-value" value={gig.city} readOnly />
      </div>

      <div className="gig-info-group">
        <label className="gig-info-label">Description</label>
        <textarea className="gig-info-textarea" value={gig.description} readOnly rows={4} />
      </div>

      <div className="gig-info-group">
        <label className="gig-info-label">Date Posted</label>
        <input
          className="gig-info-value"
          value={gig.postingDate?.split("T")[0] || gig.createdAt?.split("T")[0]}
          readOnly
        />
      </div>

      <div className="gig-info-group">
        <label className="gig-info-label">Expires</label>
        <input className="gig-info-value" value={gig.expiryDate?.split("T")[0]} readOnly />
      </div>

      <div className="gig-info-group">
        <label className="gig-info-label">Posted By</label>
        <input className="gig-info-value" value={gig.username || "Unknown"} readOnly />
      </div>

      <button
        className="view-profile-btn"
        onClick={() => navigate(`/user-view-profile/${gig.userId}`)}
      >
        View User Profile
      </button>

      <button
        className="back-btn"
        onClick={() => navigate(-1)}
        style={{ marginTop: "10px" }}
      >
        ← Back
      </button>
    </div>
  );
};

export default UserGig;
